	return filtered
}

client_routes_test.go::makeClientRoutePa.source:
func makeClientRoutePairs(connectionIDs, hostIDs []string) []pair {
	pairs := make([]pair, 0, len(connectionIDs)*len(hostIDs))
	for _, connectionID := range connectionIDs {
		for _, hostID := range hostIDs {
			pairs = append(pairs, pair{connectionID: connectionID, hostID: hostID})
		}
	}
	return pairs
}

client_routes_test.go::sortClientRoutes.source:
func sortClientRoutes(xs []clientRoute) {
	sort.Slice(xs, func(i, j int) bool {
		a, b := xs[i], xs[j]

		if a.connectionID != b.connectionID {
			return a.connectionID < b.connectionID // or bytes.Compare if raw [16]byte
		}
		return a.hostID < b.hostID
	})
}

cloud_cluster_test.go::writeYamlToTempFi.source:
func writeYamlToTempFile(obj any) (string, error) {
	f, err := os.CreateTemp(os.TempDir(), "gocql-cloud")
	if err != nil {
		return "", fmt.Errorf("create temp file: %w", err)
	}
	if err := f.Close(); err != nil {
		return "", fmt.Errorf("close temp file: %w", err)
	}

	buf, err := yaml.Marshal(obj)
	if err != nil {
		return "", fmt.Errorf("marshal yaml: %w", err)
	}
	if err := os.WriteFile(f.Name(), buf, 0600); err != nil {
		return "", fmt.Errorf("write to file %q: %w", f.Name(), err)
	}

	return f.Name(), nil
}

