	rows, err := Run(context.Background(), s, b, options)
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	if !rows.Next() {
		t.Fatalf("expected one row: %v", rows.Err())
	}
	row, err := rows.Clone()
	if err != nil {
		t.Fatal(err)
	}
	if rows.Next() {
		t.Fatal("expected exactly one row")
	}
	if err := rows.Err(); err != nil {
		t.Fatal(err)
	}
	return row
}

