	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	var result []DynamicRow
	for rows.Next() {
		row, err := rows.Clone()
		if err != nil {
			t.Fatal(err)
		}
		result = append(result, row)
	}
	if err := rows.Err(); err != nil {
		t.Fatal(err)
	}
	return result
}

