func trimQueries(in []string) []string {
	queries := in[:0]
	for _, q := range in {
		q = strings.TrimSpace(q)
		if q == "" {
			continue
		}
		if len(q) != 0 {
			queries = append(queries, q)
		}
	}
	return queries
}

