			hello = &tls.ClientHelloInfo{}
			*hello = *argHello
			return nil, nil
		},
	}).Handshake

func() {
		_, _ = io.Copy(backendConn, peekedBytes)
		_, _ = io.Copy(backendConn, conn)
		wg.Done()
	}

