			// all queries are running on the same node
			conn := getRandomConn(t, session)
			if reason := tc.gate(t, session, conn); reason != "" {
				t.Skip(reason)
			}

			runMetadataChangedFlow(t, session, conn, tc.table)
		})
	}
}

