func TestSerializationSimpleTypesCassandra(t *testing.T) {
	t.Parallel()

	const (
		pkColumn   = "test_id"
		testColumn = "test_col"
	)

	typeCases := valcases.GetSimple()

	session := createSession(t)
	defer session.Close()

